function wordCount(text) {
  const words = text.toLowerCase().split(/\s+/).filter(Boolean).sort();
  const counts = new Map();
  for (let i = 0; i < words.length; i++) {
    let run = 1;
    while (words[i + 1] === words[i]) { run++; i++; }
    counts.set(words[i], run);
  }
  return counts;
}

